from typing import List, Optional

from taf.rfrl.csv4all.resources.test_cases import UpgradeRollbackTest
from taf.rfrl.csv4all.resources.utilities.decorators import method_decorator
from taf.rfrl.csv4all.resources.utilities.exceptions import FatalError
from taf.rfrl.csv4all.resources.utilities.utilities import test_logger


class LiveUpdateTest(UpgradeRollbackTest):

    def __init__(self, nodes_details: List[dict], test_nodes_details: List[dict], iterations_per_node: int,
                 report: bool, calculate_kpi: Optional[bool] = False, kpi_targets: Optional[dict] = None,
                 use_dcap: Optional[bool] = False, qc_domain: Optional[str] = None, qc_id: Optional[str] = None,
                 qc_project: Optional[str] = None, customers_list: Optional[list] = None,
                 report_comment: Optional[str] = None, sw_build: Optional[str] = None, topology: Optional[str] = None,
                 use_external_storage: Optional[bool] = False, download_path: Optional[str] = None,
                 use_testpackage: Optional[bool] = False, restore_to_target_sw: Optional[bool] = True,
                 l3_call_method: Optional[callable] = None, stop_test_after_fail: Optional[bool] = False,
                 artifactory_location: Optional[str] = "espoo2", package_suffix: Optional[str] = "A54",
                 synchronize_software_on_passive: Optional[bool] = False,
                 yaft_path: Optional[str] = "/home/ute/YAFT", virtualenv_dir: Optional[str] = None,
                 rollback_reverse_order: bool = False, detailed_console_log: bool = True, ru_update_sw: bool = False,
                 collect_passed_logs: int = 0, swconfig_modification: bool = True, hwf_migration_check: bool = True,
                 kpi_to_calculate: list = None, diagnostic_check: bool = False):
        super().__init__(nodes_details, test_nodes_details, iterations_per_node, report, calculate_kpi, kpi_targets,
                         use_dcap, qc_domain, qc_id, qc_project, customers_list, report_comment,
                         sw_build, topology, use_external_storage, download_path, use_testpackage, restore_to_target_sw,
                         l3_call_method, stop_test_after_fail, artifactory_location, package_suffix,
                         synchronize_software_on_passive, yaft_path, virtualenv_dir, rollback_reverse_order,
                         detailed_console_log, ru_update_sw, collect_passed_logs, swconfig_modification,
                         hwf_migration_check, kpi_to_calculate, diagnostic_check=diagnostic_check)
        self.reset_incrementation = False

    @method_decorator()
    def live_update_precheck(self, node):
        if not node.check_if_live_update():
            raise FatalError("Live Update not performed, please check if paths are correct")
        if self.synchronize_software_on_passive:
            node.synchronize_software_on_passive()
        else:
            if self.iterations_per_node > 1:
                test_logger("Synchronize software on passive is False, loops cant be done. "
                            "Iterations number will be set to 1", "WARN")
